* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #f4f6f8;
  color: #141821;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.partner360 {
  min-height: 100vh;
  padding: 22px;
  background: #f4f6f8;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  background: #141b31;
  color: white;
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 14px;
}

.identity {
  display: flex;
  gap: 14px;
  align-items: center;
}

.avatar {
  width: 58px;
  height: 58px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: white;
  color: #2257d6;
  font-weight: 900;
  font-size: 22px;
}

.identity p {
  margin: 0 0 3px;
  color: #91a4d8;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.identity h1 {
  margin: 0;
  font-size: 28px;
  letter-spacing: 0;
}

.identity span {
  display: block;
  margin-top: 5px;
  color: #d3daea;
  font-weight: 700;
}

.hero-actions {
  display: flex;
  gap: 10px;
  align-items: center;
}

.hero-actions button {
  border: 0;
  min-height: 38px;
  padding: 0 15px;
  border-radius: 6px;
  background: white;
  color: #141b31;
  font-weight: 900;
  cursor: pointer;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.kpis article {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 17px;
  min-height: 104px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.07);
  display: grid;
  gap: 8px;
}

.kpis span {
  color: #647085;
  font-weight: 800;
}

.kpis strong {
  font-size: 24px;
  line-height: 1;
}

.layout {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 14px;
}

.panel {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 18px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.06);
}

.panel.wide {
  grid-column: span 2;
}

.panel-title {
  margin-bottom: 14px;
}

.panel-title h2 {
  margin: 0;
  font-size: 18px;
}

.panel-title span {
  display: block;
  margin-top: 4px;
  color: #69768a;
  font-size: 13px;
  font-weight: 700;
}

.profile-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.profile-grid div {
  border: 1px solid #e3e9f2;
  border-radius: 7px;
  padding: 12px;
  background: #f8fafc;
}

.profile-grid .wide {
  grid-column: span 2;
}

label {
  display: block;
  color: #6b778a;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.profile-grid strong {
  font-size: 13px;
  word-break: break-word;
}

.list {
  display: grid;
  gap: 10px;
}

.list-row {
  min-height: 58px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.list-row strong {
  display: block;
  font-size: 14px;
}

.list-row span {
  display: block;
  margin-top: 3px;
  color: #6b778a;
  font-size: 12px;
  font-weight: 700;
}

.list-row b {
  white-space: nowrap;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid #e6ecf4;
  padding: 11px 10px;
  text-align: left;
  font-size: 13px;
}

th {
  background: #f8fafc;
  color: #445066;
  font-weight: 900;
}

td strong {
  display: block;
}

em {
  display: inline-flex;
  border-radius: 999px;
  padding: 4px 8px;
  font-style: normal;
  font-size: 11px;
  font-weight: 900;
}

em.success {
  background: #dcfce7;
  color: #166534;
}

em.warning {
  background: #fef3c7;
  color: #92400e;
}

em.danger {
  background: #fee2e2;
  color: #991b1b;
}

em.info {
  background: #dbeafe;
  color: #1e40af;
}

.soft-empty,
.table-empty,
.empty {
  padding: 28px 14px;
  color: #7a8495;
  font-weight: 800;
  text-align: center;
  border: 1px dashed #d7dee9;
  border-radius: 8px;
  background: #f8fafc;
}

.empty {
  min-height: 280px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
}

.empty strong {
  font-size: 18px;
  color: #141821;
}

footer {
  margin-top: 16px;
  color: #6d788a;
  font-size: 12px;
  font-weight: 700;
}

@media print {
  .no-print {
    display: none !important;
  }
  body,
  .partner360 {
    background: white;
  }
  .partner360 {
    padding: 0;
  }
  .hero {
    color: #141821;
    background: white;
    border: 1px solid #dce4ef;
  }
  .identity span,
  .identity p {
    color: #647085;
  }
  .panel,
  .kpis article {
    box-shadow: none;
    break-inside: avoid;
  }
}

