            <div><label>Registration No</label><strong>{text(header.registrationNumber)}</strong></div>
            <div><label>Email</label><strong>{text(header.email)}</strong></div>
            <div><label>Phone</label><strong>{text(header.phone)}</strong></div>
            <div className="wide"><label>Address</label><strong>{text(header.address)} · {text(header.postalCode)} {text(header.city)} · {text(header.country)}</strong></div>
            <div><label>Created</label><strong>{date(header.createdAt)}</strong></div>
            <div><label>Last document</label><strong>{date(header.lastDocumentDate)}</strong></div>
          </div>
        </article>

        <article className="panel">
          <div className="panel-title">
            <h2>Top products</h2>
            <span>Most relevant items for this partner</span>
          </div>

          <div className="list">
            {topProducts.length ? topProducts.map((row, index) => (
              <div className="list-row" key={index}>
                <div>
                  <strong>{text(row.productName)}</strong>
                  <span>{text(row.productCode)} · Qty {money(row.quantity)}</span>
                </div>
                <b>{money(row.totalAmount)} EUR</b>
              </div>
            )) : <div className="soft-empty">No product history</div>}
          </div>
        </article>

        <article className="panel wide">
          <div className="panel-title">
            <h2>Recent documents</h2>
            <span>Latest invoices, receipts, orders and purchase documents</span>
          </div>

          <table>
            <thead>
              <tr>
                <th>Document</th>
                <th>Type</th>
                <th>Date</th>
                <th>Status</th>
                <th>Total</th>
                <th>Open</th>
              </tr>
            </thead>
            <tbody>
              {documents.length ? documents.map((row, index) => (
                <tr key={index}>
                  <td><strong>{text(row.documentNumber)}</strong></td>
                  <td>{text(row.documentType)}</td>
                  <td>{date(row.documentDate)}</td>
                  <td><em className={statusClass(row.status)}>{text(row.status)}</em></td>
                  <td>{money(row.totalAmount)} {text(row.currencyCode, "EUR")}</td>
                  <td>{money(row.openAmount)} {text(row.currencyCode, "EUR")}</td>
                </tr>
              )) : (
                <tr>
                  <td colSpan="6" className="table-empty">No documents found</td>
                </tr>
              )}
            </tbody>
          </table>
        </article>
      </section>

      <footer>
        Printed: {text(model.printedAt, "")} by {text(model.printedBy, "")}
      </footer>
    </main>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
